*** Begin Patch
*** Update File: /root/local.rules
@@
-# Write your rule(s) here.
-# Requirement: raise exactly sid:1000001 for the custom exfil pattern.
+alert http any any -> any any (
+  msg:"TLM exfil telemetry POST";
+  flow:established,to_server;
+
+  http.method;
+  content:"POST";
+
+  http.uri;
+  content:"/telemetry/v2/report";
+  startswith;
+  endswith;
+
+  http.header;
+  content:"X-TLM-Mode|3a| exfil";
+
+  http_client_body;
+  content:"blob=";
+
+  http_client_body;
+  pcre:"/blob=[A-Za-z0-9+\\/]{80,}={0,2}/";
+
+  http_client_body;
+  pcre:"/sig=[0-9A-Fa-f]{64}(?![0-9A-Fa-f])/";
+
+  sid:1000001;
+  rev:1;
+)
*** End Patch

